const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-62.27, -38.79]); // Ingeniero White port, Argentina
    const areaOfInterest = point.buffer(10000); // 10 km radius

    const date1_start = '2025-01-30';
    const date1_end = '2025-01-31';
    const date2_start = '2025-03-11';
    const date2_end = '2025-03-12';

    // 2. Data Acquisition & Check
    const get_s1_image = function(startDate, endDate, aoi) {
        let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
            .filterBounds(aoi)
            .filterDate(startDate, endDate)
            .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
            .filter(ee.Filter.eq('instrumentMode', 'IW'));

        // If no image on the exact day, try a wider window (+/- 2 days)
        if (collection.size().getInfo() === 0) {
            const wideStartDate = ee.Date(startDate).advance(-2, 'day');
            const wideEndDate = ee.Date(endDate).advance(2, 'day');
            collection = ee.ImageCollection('COPERNICUS/S1_GRD')
                .filterBounds(aoi)
                .filterDate(wideStartDate, wideEndDate)
                .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
                .filter(ee.Filter.eq('instrumentMode', 'IW'));
        }
        return collection.mosaic().clip(aoi);
    };

    const image1 = get_s1_image(date1_start, date1_end, areaOfInterest);
    const image2 = get_s1_image(date2_start, date2_end, areaOfInterest);

    // Check if images are available
    const image1_count = image1.bandNames().size().getInfo();
    const image2_count = image2.bandNames().size().getInfo();

    if (image1_count === 0 || image2_count === 0) {
        console.log(`Image found for Jan 2025: ${image1_count > 0}`);
        console.log(`Image found for Mar 2025: ${image2_count > 0}`);
        console.log("Empty Collection: No Sentinel-1 images found for one or both dates.");
        console.log("A"); // The data is from the future (2025). GEE returns empty collections for future dates.
        return;
    }

    // This block will not be reached due to future dates.
    // Kept for logical completeness if dates were in the past.
    const waterThreshold = -18; // VH backscatter threshold in dB for water

    const water1 = image1.select('VH').lt(waterThreshold).selfMask();
    const water2 = image2.select('VH').lt(waterThreshold).selfMask();

    // 3. Processing & Calculation
    const pixelArea = ee.Image.pixelArea();
    const calculateArea = (image) => {
        const area = image.multiply(pixelArea).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: areaOfInterest,
            scale: 100, // Sentinel-1 resolution is ~10m, but 100m is safer for large area
            maxPixels: 1e9
        });
        return ee.Number(area.get('VH')).divide(1e6); // Area in sq km
    };

    const inundatedArea1 = calculateArea(water1).getInfo();
    const inundatedArea2 = calculateArea(water2).getInfo();

    // 4. Validation & Final Answer
    if (inundatedArea1 === null || inundatedArea2 === null || isNaN(inundatedArea1) || isNaN(inundatedArea2)) {
         console.log(`Jan 2025 Area (km2): ${inundatedArea1}`);
         console.log(`Mar 2025 Area (km2): ${inundatedArea2}`);
         console.log("Calculation Failure: Result is null or NaN.");
         console.log("C3");
         return;
    }

    console.log(`Inundation Area on Jan 30, 2025: ${inundatedArea1.toFixed(2)} km2`);
    console.log(`Inundation Area on Mar 11, 2025: ${inundatedArea2.toFixed(2)} km2`);
    console.log(`Change in inundated area: ${(inundatedArea2 - inundatedArea1).toFixed(2)} km2`);

    if (inundatedArea2 > inundatedArea1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    // Handle potential errors like incorrect keys, GEE initialization failures, etc.
    console.error(err);
    console.log("D"); // Generic error catch
});
